referenceSolutions.javascript:
export function solve(operations) {
  let history = [];
  return operations.map(([op, args]) => {
    if (op === "log") {
      history.push(args);
      return null;
    }
    if (op === "clear") {
      history = [];
      return null;
    }
    return history.slice();
  });
}

